'use strict';
// Production DOM and sandboxed preload; IPC responses are memory-only fixtures.
const {app,BrowserWindow,ipcMain}=require('electron'),assert=require('node:assert/strict'),path=require('node:path');
const {FeedbackSession}=require('../../src/core/feedback.cjs');
let window,session,cancels=0,sends=0,late=[],failSend=false;const payload={category:'问题反馈',message:'保留我的留言',includeLogs:true};
const fallback={preview:p=>({text:'已预览 '+p.message,previewId:'a'.repeat(32)}),cancel:()=>{}};
ipcMain.handle('nettools:snapshot',()=>({ok:true,data:{version:'5.0.2',settings:{},guard:{},now:0}}));
ipcMain.handle('nettools:feedback-preview',async(_event,p)=>{const result=session.preview(p,{name:'捞鱼的网络工具',version:'5.0.2',logs:'scanfiles1'});if(late.length)await new Promise(r=>late.push(r));return {ok:true,data:result};});
ipcMain.handle('nettools:feedback-cancel',(_event,p)=>{cancels++;session.cancel(p);return {ok:true,data:{cancelled:true}};});
ipcMain.handle('nettools:feedback-send',async(_event,p)=>{try{const result=await session.send(p,{getEndpoint:()=> 'https://qyapi.weixin.qq.com/cgi-bin/webhook/send?key=fixture',post:async()=>{sends++;if(failSend)throw Error("fixture offline");return {errcode:0};}});return {ok:true,data:result};}catch(e){return {ok:false,error:{message:e.message}};}});
app.whenReady().then(async()=>{
 session=typeof FeedbackSession==='function'?new FeedbackSession():fallback;
 window=new BrowserWindow({width:1120,height:780,show:false,webPreferences:{preload:path.resolve('src/preload.cjs'),nodeIntegration:false,contextIsolation:true,sandbox:true}});await window.loadFile(path.resolve('ui/index.html'));
 const evaluate=s=>window.webContents.executeJavaScript(s,true),settle=()=>require('../../src/core/desktop-acceptance.cjs').settlePage(window),click=async id=>{await evaluate(`document.getElementById(${JSON.stringify(id)}).click()`);await settle();},form=async()=>{await evaluate(`document.getElementById('feedback-message').value=${JSON.stringify(payload.message)};document.getElementById('feedback-category').value='问题反馈';document.getElementById('feedback-logs').checked=true;`);},visible=()=>evaluate("!document.getElementById('feedback-preview').classList.contains('hidden')"),disabled=()=>evaluate("document.getElementById('send-feedback').disabled");
 await form();await click('open-feedback');assert.equal(await disabled(),true,'Send must be disabled until preview');
 for(const [id,event,assignment]of [['feedback-message','input',"value+=' 新内容'"],['feedback-category','change',"value='建议'"],['feedback-logs','change','checked=false']]){
  await form();await click('preview-feedback');assert.equal(await visible(),true);assert.equal(await disabled(),false);
  await evaluate(`{const el=document.getElementById(${JSON.stringify(id)});el.${assignment};el.dispatchEvent(new Event(${JSON.stringify(event)},{bubbles:true}));}`);await settle();assert.equal(await visible(),false,id+' must hide stale preview');assert.equal(await disabled(),true);assert.match(await evaluate("document.getElementById('toast').textContent"),/重新预览/);
 }
 for(const close of ["document.querySelector('[data-close=feedback-modal]').click()","document.dispatchEvent(new KeyboardEvent('keydown',{key:'Escape'}))"]){await form();await click('preview-feedback');await evaluate(close);await settle();await click('open-feedback');assert.equal(await visible(),false);assert.equal(await disabled(),true);assert.equal(await evaluate("document.getElementById('feedback-message').value"),payload.message);}
 await form();late=[true];await evaluate("document.getElementById('preview-feedback').click()");await evaluate("document.getElementById('feedback-message').value+=' change';document.getElementById('feedback-message').dispatchEvent(new Event('input'))");await settle();for(const resolve of late.slice(1))resolve();late=[];await settle();assert.equal(await visible(),false,'late preview must not revive Send');assert.equal(await disabled(),true);
 await form();await click('preview-feedback');failSend=true;await click('send-feedback');assert.equal(sends,1);assert.equal(await disabled(),true);assert.equal(await evaluate("document.getElementById('feedback-message').value"),payload.message);await click('send-feedback');assert.equal(sends,1);failSend=false;await click('preview-feedback');await evaluate("window.fixtureShow=show;show=(id,visible)=>{if(id==='feedback-modal'&&!visible)throw Error('fixture auxiliary UI failure');return window.fixtureShow(id,visible);};undefined;");await click('send-feedback');assert.equal(sends,2);assert.match(await evaluate("document.getElementById('toast').textContent"),/\u5df2\u9001\u8fbe/,'confirmed send must not become failure on UI cleanup');await evaluate("show=window.fixtureShow;show('feedback-modal',false);");assert.ok(cancels>=6);
 await form();await click('open-feedback');await click('preview-feedback');await evaluate("document.getElementById('feedback-modal').remove()");await settle();assert.equal(session.active,null,'unmounted modal must revoke host preview');
 process.stdout.write(JSON.stringify({productionDom:true,productionPreload:true,edits:true,closeEscape:true,lateIgnored:true,singleSend:true,unmount:true})+'\n');window.destroy();app.exit(0);
}).catch(error=>{console.error(error.stack);window?.destroy();app.exit(1);});
